            // [64] BB\script\output\_sce03_chr060_00_eng#14
            d[@"BB\script\output\_sce03_chr060_00_eng#14"] = (s) => {
                s = s.Replace("<RDFG 54342><E800 507><E145 18 0><E800 509><E041 18 7><E025 3>Ten years ago, <E049><E003 10><E145 18 10><E025 2>my older brother, <E049><E003 6>who was the Director of\r\nProsecutions at the time, <E049><E003 8><E025 4>was murdered.", "Il y a dix ans, mon frère aîné, alors chef des procureurs,\r\nfut assassiné.\r\nEt le meurtrier, vous ne l'ignorez point... était un étudiant visiteur venu\r\nd'Extrême-Orient.");
                s = s.Replace("<E800 510><E041 18 7><E025 3>And the killer, <E049><E003 8>as you know...<E003 15>was a visiting student from\r\nthe Far East.", "Il y a dix ans, mon frère aîné, alors chef des procureurs,\r\nfut assassiné.\r\nEt le meurtrier, vous ne l'ignorez point... était un étudiant visiteur venu\r\nd'Extrême-Orient.");
                s = s.Replace("<E800 511><E563><E800 513><E145 18 0><E800 514><E117 18 35><E800 515><E003 15><E800 517><E041 18 7><E025 2>Not a single day goes by...<E003 8><E164 18 13 1 2 5 0 2 1><E139 18><E025 1>when I don't curse the name\r\nAsogi!", "Il ne se passe pas un seul jour... sans que je ne maudisse le nom\r\nd'Asogi !");
                s = s.Replace("<E800 518><E563><E800 521><E549 8 0 40 3><E800 522><E167 3 82 5 0 5 25 40 3><E800 523><E171 3 5 0 10 2><E800 524><E131><E800 526><E041 3 2><E025 3>Genshin Asogi <E049><E003 8><E025 2><E145 3 83><E139 3>was Kazuma-sama's <E145 18 0>father.", "Genshin Asogi était le père de monsieur Kiyô.\r\nQuelle cruelle ironie du sort est-ce là, dix ans plus tard ?\r\nLe fils de cet homme va me crucifier dans un simulacre de procès ?");
                s = s.Replace("<E800 527><E563><E800 529><E164 18 9 1 2 42 0 0 1><E800 530><E139 18><E800 532><E041 18 7><E025 3>So what cruel twist of fate is this now, <E049><E145 3 77><E171 3 5 1 9 2><E003 10>ten years later?", "Genshin Asogi était le père de monsieur Kiyô.\r\nQuelle cruelle ironie du sort est-ce là, dix ans plus tard ?\r\nLe fils de cet homme va me crucifier dans un simulacre de procès ?");
                s = s.Replace("<E800 533><E041 18 7><E025 2><E333>The man's son is to crucify me <E145 3 72><E173 3 5 14 2>in some kangaroo court?", "Genshin Asogi était le père de monsieur Kiyô.\r\nQuelle cruelle ironie du sort est-ce là, dix ans plus tard ?\r\nLe fils de cet homme va me crucifier dans un simulacre de procès ?");
                s = s.Replace("<E800 534><E041 1 0><E025 3>I still don't understand why Lord Stronghart apprenticed\r\nKazuma to you.", "Je ne comprends toujours pas pourquoi Lord Harry Caine a placé Kazuma en apprentissage auprès de vous.\r\nC'est sa méthode. Il connaissait sans doute la véritable identité\r\ndu jeune homme depuis le début.");
                s = s.Replace("<E800 535><E563><E800 537><E145 18 0><E800 538><E003 10><E800 540><E041 18 7><E025 3>It's what he does.<E049><E003 10> <E025 2>No doubt he knew of the young man's\r\ntrue identity from the outset.", "Je ne comprends toujours pas pourquoi Lord Harry Caine a placé Kazuma en apprentissage auprès de vous.\r\nC'est sa méthode. Il connaissait sans doute la véritable identité\r\ndu jeune homme depuis le début.");
                s = s.Replace("<E800 541><E563><E800 543><E136 3 68 10><E800 544><E117 3 25><E800 545><E144 3><E800 547><E041 3 2><E025 2><E330>But what could he have been hoping to achieve?", "Mais quel pouvait bien être son but ?\r\nEt n'oublions pas que cela ne fait que huit jours que Kazuma a recouvré la mémoire.\r\nPourquoi Lord Harry Caine confierait-il ce procès à une telle personne ?");
                s = s.Replace("<E800 548><E041 1 0><E025 2>And let's not forget that it was only eight days ago that\r\nKazuma recovered from his amnesia.", "Mais quel pouvait bien être son but ?\r\nEt n'oublions pas que cela ne fait que huit jours que Kazuma a recouvré la mémoire.\r\nPourquoi Lord Harry Caine confierait-il ce procès à une telle personne ?");
                s = s.Replace("<E800 549><E041 1 0><E025 2>Why would Lord Stronghart <E145 3 77><E171 3 5 0 10 2>assign this trial to somebody\r\nlike that?", "Mais quel pouvait bien être son but ?\r\nEt n'oublions pas que cela ne fait que huit jours que Kazuma a recouvré la mémoire.\r\nPourquoi Lord Harry Caine confierait-il ce procès à une telle personne ?");
                s = s.Replace("<E800 550><E563><E800 552><E145 18 4><E800 553><E139 18><E800 555><E041 18 7><E025 4><E169 6 0>Hm...<E003 10><E169 6 3><E025 3><E145 3 82><E173 3 5 20 2>Asogi...", "Hum... Asogi...\r\nCe nom est l'incarnation même de mon supplice.\r\nLe fléau que vous représentez, vous autres Japonais.\r\n(C'est cela... Votre haine viscérale envers nous tous...)");
                s = s.Replace("<E800 556><E041 18 7><E025 3>That name <E049><E003 10><E145 18 0><E333>is the very epitome of my bane.<E145 3 72>", "Hum... Asogi...\r\nCe nom est l'incarnation même de mon supplice.\r\nLe fléau que vous représentez, vous autres Japonais.\r\n(C'est cela... Votre haine viscérale envers nous tous...)");
                s = s.Replace("<E800 557><E563><E800 559><E164 18 9 1 2 42 0 0 1><E800 560><E139 18><E800 562><E041 18 7><E025 3>The bane that is you <E006>Nipponese<E005>.", "Hum... Asogi...\r\nCe nom est l'incarnation même de mon supplice.\r\nLe fléau que vous représentez, vous autres Japonais.\r\n(C'est cela... Votre haine viscérale envers nous tous...)");
                s = s.Replace("<E800 563><E041 1 0><E025 3><E007>(Right...<E003 8> Your hatred of all us Japanese...)", "Hum... Asogi...\r\nCe nom est l'incarnation même de mon supplice.\r\nLe fléau que vous représentez, vous autres Japonais.\r\n(C'est cela... Votre haine viscérale envers nous tous...)");
                return s;
