            // [65] BB\script\output\_sce03_chr060_00_eng#15
            d[@"BB\script\output\_sce03_chr060_00_eng#15"] = (s) => {
                s = s.Replace("<RDFG 54358><E800 573><E145 18 0><E800 575><E041 18 7><E025 2>I'd only just been appointed as a prosecutor when it\r\nhappened ten years ago.", "Je venais tout juste d'être nommé procureur lorsque le drame est survenu il y a dix ans.\r\nMon frère Klimt, le chef des procureurs, traquait\r\nun tueur de masse sanguinaire.\r\nLe sinistre « Démon Assassin »...");
                s = s.Replace("<E800 577><E145 18 9><E800 578><E117 18 25><E800 580><E041 18 7><E025 3>My brother Klint, <E049><E003 8><E025 2>the Director of Prosecutions,<E049><E003 8> was\r\nhunting down a mass murderer.", "Je venais tout juste d'être nommé procureur lorsque le drame est survenu il y a dix ans.\r\nMon frère Klimt, le chef des procureurs, traquait\r\nun tueur de masse sanguinaire.\r\nLe sinistre « Démon Assassin »...");
                s = s.Replace("<E800 581><E041 1 0><E025 3>The so-called <E003 6><E330>‘Professor’...", "Je venais tout juste d'être nommé procureur lorsque le drame est survenu il y a dix ans.\r\nMon frère Klimt, le chef des procureurs, traquait\r\nun tueur de masse sanguinaire.\r\nLe sinistre « Démon Assassin »...");
                s = s.Replace("<E800 582><E563><E800 584><E145 18 0><E800 585><E003 10><E800 587><E041 18 7><E025 3>Assigned to the investigation as his partner...", "Affecté à cette enquête comme son partenaire...\r\n...se trouvait un certain étudiant visiteur détaché auprès de Scotland Yard.\r\nEt c'était Genshin Asogi ?\r\nPrécisément.");
                s = s.Replace("<E800 588><E041 18 7><E025 2>...was a certain <E006>visiting student<E005><E003 4> dispatched from Scotland\r\nYard.", "Affecté à cette enquête comme son partenaire...\r\n...se trouvait un certain étudiant visiteur détaché auprès de Scotland Yard.\r\nEt c'était Genshin Asogi ?\r\nPrécisément.");
                s = s.Replace("<E800 589><E041 1 0><E333><E025 3>And that was <E006>Genshin Asogi<E005>?", "Affecté à cette enquête comme son partenaire...\r\n...se trouvait un certain étudiant visiteur détaché auprès de Scotland Yard.\r\nEt c'était Genshin Asogi ?\r\nPrécisément.");
                s = s.Replace("<E800 590><E563><E800 592><E145 18 1><E800 593><E118 18 1.3><E800 594><E003 10><E800 596><E041 18 7><E025 3>Exactly.", "Affecté à cette enquête comme son partenaire...\r\n...se trouvait un certain étudiant visiteur détaché auprès de Scotland Yard.\r\nEt c'était Genshin Asogi ?\r\nPrécisément.");
                s = s.Replace("<E800 597><E563><E800 599><E145 18 12><E800 600><E118 18 1.2><E800 601><E003 15><E800 603><E041 18 7><E025 2>I developed a deep respect for the man.<E049><E003 8> He seemed\r\nnoble-minded and chivalrous in the extreme to me.", "J'avais conçu une profonde admiration pour cet individu. Il m'apparaissait\r\nd'une noblesse d'âme et d'une bravoure incomparables.\r\n...Mais aucun de nous n'avait percé à jour sa véritable nature.");
                s = s.Replace("<E800 604><E041 18 7><E025 4>...But <E049><E003 18><E025 1><E145 18 3><E046><E087>none of us saw <E006>the true nature<E005> of the man.", "J'avais conçu une profonde admiration pour cet individu. Il m'apparaissait\r\nd'une noblesse d'âme et d'une bravoure incomparables.\r\n...Mais aucun de nous n'avait percé à jour sa véritable nature.");
                s = s.Replace("<E800 605><E563><E800 606><E003 10><E800 608><E145 18 0><E800 609><E118 18 0.6><E800 610><E003 35><E800 612><E085 3 6><E800 613><E003 20><E800 615><E041 18 7><E025 3>So I lost everything <E145 18 2>when it happened.", "J'ai donc tout perdu lorsque le malheur a frappé.\r\nMon frère vénéré... les êtres en qui j'avais foi... et\r\ntoute illusion de voir la justice triompher de l'infamie !\r\nOh... quelle horreur...");
                s = s.Replace("<E800 616><E041 18 7><E025 3>My esteemed brother...<E049><E003 10>the people I believed in...<E049><E003 15><E164 18 13 1 2 8 0 3 1><E118 18 1.2><E139 18><E025 1>and\r\nany semblance of right prevailing over wrong!", "J'ai donc tout perdu lorsque le malheur a frappé.\r\nMon frère vénéré... les êtres en qui j'avais foi... et\r\ntoute illusion de voir la justice triompher de l'infamie !\r\nOh... quelle horreur...");
                s = s.Replace("<E800 617><E563><E800 620><E549 8 0 40 3><E800 621><E167 3 72 5 0 5 25 40 3><E800 622><E171 3 5 1 9 2><E800 623><E003 8><E800 624><E145 18 0><E800 625><E131><E800 626><E003 8><E800 628><E041 3 2><E025 3>Oh...<E049><E003 10>how awful...", "J'ai donc tout perdu lorsque le malheur a frappé.\r\nMon frère vénéré... les êtres en qui j'avais foi... et\r\ntoute illusion de voir la justice triompher de l'infamie !\r\nOh... quelle horreur...");
                s = s.Replace("<E800 629><E563><E800 631><E145 18 12><E800 632><E118 18 1.2><E800 633><E003 15><E800 635><E041 18 7><E025 3>To avenge my brother, <E049><E003 10><E025 2>I prosecuted <E145 3 77>in Asogi's trial.", "Pour venger mon frère, j'ai porté l'accusation au procès d'Asogi.\r\nCela n'aurait jamais dû m'être accordé, mais j'ai harcelé\r\nle procureur en titre jusqu'à ce qu'il cède.");
                s = s.Replace("<E800 636><E041 18 7><E025 3>It wouldn't ordinarily have been allowed, <E049><E003 10><E025 2>but I\r\nbeleaguered the ascribed prosecutor until he consented.", "Pour venger mon frère, j'ai porté l'accusation au procès d'Asogi.\r\nCela n'aurait jamais dû m'être accordé, mais j'ai harcelé\r\nle procureur en titre jusqu'à ce qu'il cède.");
                s = s.Replace("<E800 637><E563><E800 639><E145 3 83><E800 640><E003 5><E800 642><E041 3 2><E025 3>What do you mean <E049><E003 8><E333>by the ascribed prosecutor?", "Que voulez-vous dire par le procureur en titre ?\r\nL'homme qui supervisait l'enquête du Démon Assassin :\r\nLord Harry Caine.\r\nAttendez, quoi ?! Lord Harry Caine ?");
                s = s.Replace("<E800 643><E563><E800 645><E145 18 0><E800 646><E003 30><E800 648><E041 18 7><E025 3>The man in charge of the Professor case inquiry:<E049><E003 15>\r\n<E239>Lord Mael Stronghart.", "Que voulez-vous dire par le procureur en titre ?\r\nL'homme qui supervisait l'enquête du Démon Assassin :\r\nLord Harry Caine.\r\nAttendez, quoi ?! Lord Harry Caine ?");
                s = s.Replace("<E800 649><E145 3 67><E800 650><E041 1 0><E025 1><E331><E342>Wait, <E003 12>what?!<E003 14>\r\n<E025 3>Lord Stronghart?", "Que voulez-vous dire par le procureur en titre ?\r\nL'homme qui supervisait l'enquête du Démon Assassin :\r\nLord Harry Caine.\r\nAttendez, quoi ?! Lord Harry Caine ?");
                s = s.Replace("<E800 651><E041 18 7><E025 3>He was a highly accomplished prosecutor.<E049><E003 10> But he agreed\r\nto relinquish the trial to me and act as my adviser instead.", "C'était un magistrat hors pair. Il a consenti à me céder\r\nle siège et à me guider comme conseiller.\r\nDepuis lors, il est l'unique individu envers qui je nourrisse\r\nune dette infinie.");
                s = s.Replace("<E800 652><E563><E800 654><E145 18 12><E800 655><E003 25><E800 657><E041 18 7><E025 3>Since that time, <E049><E003 8><E025 2>he's the one person <E145 3 64>to whom I've felt\r\nindebted.", "C'était un magistrat hors pair. Il a consenti à me céder\r\nle siège et à me guider comme conseiller.\r\nDepuis lors, il est l'unique individu envers qui je nourrisse\r\nune dette infinie.");
                s = s.Replace("<E800 658><E041 3 2><E145 3 65><E025 2>I'm sure he must have seen your zeal for the case and\r\nrecognised your potential as a prosecutor.", "Il a sûrement décelé votre ferveur pour cette cause et\r\npressenti votre prodigieux avenir de procureur.\r\nQuoi qu'il en soit, les années ont passé, et voici que plus tôt cette année débarquait à Londres...\r\nnul autre que vous.\r\nAh !\r\nEt pour couronner le tout... sous les traits d'un avocat.");
                s = s.Replace("<E800 659><E563><E800 660><E003 10><E800 662><E145 18 0><E800 663><E118 18 1.2><E800 664><E003 20><E800 666><E041 18 7><E025 3>Anyway, <E049><E003 8><E025 3>time passed, <E049><E003 10><E025 2>but then earlier this year, <E049><E003 15><E238><E025 3>who\r\nshould arrive in London...<E003 10><E025 3>but you.", "Il a sûrement décelé votre ferveur pour cette cause et\r\npressenti votre prodigieux avenir de procureur.\r\nQuoi qu'il en soit, les années ont passé, et voici que plus tôt cette année débarquait à Londres...\r\nnul autre que vous.\r\nAh !\r\nEt pour couronner le tout... sous les traits d'un avocat.");
                s = s.Replace("<E800 668><E145 3 67><E800 669><E117 3 7><E800 670><E172 3 -7 -3 7 2 10><E800 672><E041 3 2><E025 3><E333><E342>Ah!", "Il a sûrement décelé votre ferveur pour cette cause et\r\npressenti votre prodigieux avenir de procureur.\r\nQuoi qu'il en soit, les années ont passé, et voici que plus tôt cette année débarquait à Londres...\r\nnul autre que vous.\r\nAh !\r\nEt pour couronner le tout... sous les traits d'un avocat.");
                s = s.Replace("<E800 673><E145 18 4><E800 674><E041 18 7><E025 3>And, <E049><E003 10>of all things...<E049><E003 4><E145 18 11><E118 18 0.8><E003 30><E239><E025 2>as a lawyer.", "Il a sûrement décelé votre ferveur pour cette cause et\r\npressenti votre prodigieux avenir de procureur.\r\nQuoi qu'il en soit, les années ont passé, et voici que plus tôt cette année débarquait à Londres...\r\nnul autre que vous.\r\nAh !\r\nEt pour couronner le tout... sous les traits d'un avocat.");
                // UNMATCHED: s = s.Replace("<E800 675><E563><E800 676><E003 10><E800 678><E041 1 0><E025 7>...<E003 2><E145 3 77><E118 3 0.6>...<E003 4>...", "...");
                s = s.Replace("<E800 679><E041 1 0><E025 2>I felt your animosity the first time I ever faced you in the\r\ncourtroom.", "J'ai ressenti votre hostilité dès notre premier face-à-face dans l'enceinte du tribunal.\r\nVotre dégoût viscéral et manifeste envers nous, les Japonais.\r\nJe me répétais sans cesse que c'était insensé.\r\nMais pendant tant d'années, cette rancœur avait fermenté en moi,\r\nau point que je ne pouvais plus la contenir.");
                s = s.Replace("<E800 680><E041 1 0><E025 3>Your obvious <E145 18 0><E118 18 1.2>deep loathing <E003 10><E330><E025 3>of us Japanese.<E145 3 82><E118 3 0.9><E173 3 5 15 2>", "J'ai ressenti votre hostilité dès notre premier face-à-face dans l'enceinte du tribunal.\r\nVotre dégoût viscéral et manifeste envers nous, les Japonais.\r\nJe me répétais sans cesse que c'était insensé.\r\nMais pendant tant d'années, cette rancœur avait fermenté en moi,\r\nau point que je ne pouvais plus la contenir.");
                s = s.Replace("<E800 681><E563><E800 683><E145 18 9><E800 684><E003 30><E800 686><E041 18 7><E025 3>I kept telling myself it was illogical.", "J'ai ressenti votre hostilité dès notre premier face-à-face dans l'enceinte du tribunal.\r\nVotre dégoût viscéral et manifeste envers nous, les Japonais.\r\nJe me répétais sans cesse que c'était insensé.\r\nMais pendant tant d'années, cette rancœur avait fermenté en moi,\r\nau point que je ne pouvais plus la contenir.");
                s = s.Replace("<E800 687><E563><E800 689><E145 18 0><E800 690><E118 18 1.5><E800 691><E003 6><E800 693><E041 18 7><E025 3>But for so many years, <E049><E003 8><E025 2>that hatred had festered inside me,<E049><E003 8><E164 18 13 1 2 5 1 3 0><E139 18><E339><E025 1><E145 3 83><E171 3 5 1 9 0>\r\nI could no longer control it.", "J'ai ressenti votre hostilité dès notre premier face-à-face dans l'enceinte du tribunal.\r\nVotre dégoût viscéral et manifeste envers nous, les Japonais.\r\nJe me répétais sans cesse que c'était insensé.\r\nMais pendant tant d'années, cette rancœur avait fermenté en moi,\r\nau point que je ne pouvais plus la contenir.");
                s = s.Replace("<E800 694><E563><E800 695><E003 15><E800 697><E041 1 0><E025 2>And I can understand why, <E003 12><E025 3><E145 3 82>now I know the history.", "Et je peux le comprendre, maintenant que je connais l'histoire.\r\nMais de la même façon que les Japonais ont été le poison de mon existence...\r\n...aux yeux de Kazuma Asogi, je suis le bourreau de la sienne. Le Faucheur qui\r\na expédié son père à l'échafaud.\r\nIl veut sa vengeance, et il compte bien l'assouvir à l'audience demain.");
                s = s.Replace("<E800 698><E563><E800 699><E003 8><E800 701><E145 18 0><E800 702><E003 4><E800 703><E549 8 1 40 3><E800 704><E168 3 0 5 10 40 3><E800 705><E131><E800 707><E041 18 7><E025 3>But in the same way that I've long felt the Nipponese to be\r\nthe bane of my life...", "Et je peux le comprendre, maintenant que je connais l'histoire.\r\nMais de la même façon que les Japonais ont été le poison de mon existence...\r\n...aux yeux de Kazuma Asogi, je suis le bourreau de la sienne. Le Faucheur qui\r\na expédié son père à l'échafaud.\r\nIl veut sa vengeance, et il compte bien l'assouvir à l'audience demain.");
                s = s.Replace("<E800 708><E041 18 7><E025 3>...to Kazuma Asogi, <E049><E003 8>I am the bane of his.<E049><E003 6> <E145 18 4><E144 18>The Reaper who\r\nsent his father to the gallows.", "Et je peux le comprendre, maintenant que je connais l'histoire.\r\nMais de la même façon que les Japonais ont été le poison de mon existence...\r\n...aux yeux de Kazuma Asogi, je suis le bourreau de la sienne. Le Faucheur qui\r\na expédié son père à l'échafaud.\r\nIl veut sa vengeance, et il compte bien l'assouvir à l'audience demain.");
                s = s.Replace("<E800 709><E563><E800 711><E136 18 10 13><E800 712><E117 18 25><E800 713><E003 20><E800 715><E041 18 7><E025 3>He's looking for revenge, <E049><E003 8><E239>and he intends to take it in\r\ncourt tomorrow.<E085 2 11>", "Et je peux le comprendre, maintenant que je connais l'histoire.\r\nMais de la même façon que les Japonais ont été le poison de mon existence...\r\n...aux yeux de Kazuma Asogi, je suis le bourreau de la sienne. Le Faucheur qui\r\na expédié son père à l'échafaud.\r\nIl veut sa vengeance, et il compte bien l'assouvir à l'audience demain.");
                // UNMATCHED: s = s.Replace("<E800 716><E041 1 0><E025 7>...<E003 2>...<E003 4>...", "...");
                return s;
            };

            // [66] BB\script\output\_sce03_chr060_00_eng#16
            d[@"BB\script\output\_sce03_chr060_00_eng#16"] = (s) => {
                s = s.Replace("<RDFG 54392><E800 726><E145 18 0><E800 728><E041 18 7><E025 2>Gregson's transfer to the Paris Police Prefecture had\r\nfinally been arranged for the coming month.", "La mutation de Gregson à la préfecture de police de Paris avait\r\nenfin été entérinée pour le mois prochain.\r\nMais il ne verra jamais la France désormais.\r\n...C'est une tragédie.");
                s = s.Replace("<E800 730><E145 18 2><E800 731><E118 18 1.2><E800 733><E041 18 7><E025 3>But he'll never make it to France now.<E049><E003 12>\r\n<E025 2>...It's a tragedy.", "La mutation de Gregson à la préfecture de police de Paris avait\r\nenfin été entérinée pour le mois prochain.\r\nMais il ne verra jamais la France désormais.\r\n...C'est une tragédie.");
                s = s.Replace("<E800 734><E041 1 0><E333><E342><E025 3>Oh yes, <E003 10><E025 2>come to think of it <E003 6>he did mention something\r\nabout that, <E003 6>didn't he?", "Ah oui, en y repensant, il avait mentionné quelque chose à ce sujet,\r\nn'est-ce pas ?\r\nJe me demande... est-ce chose fréquente ?\r\nÊtre muté à l'étranger, je veux dire ?\r\n...C'est la toute première fois que je vois pareille chose.");
                s = s.Replace("<E800 735><E563><E800 738><E549 8 0 40 3><E800 739><E145 18 0><E800 740><E167 3 68 5 0 5 25 40 3><E800 741><E171 3 5 1 9 0><E800 742><E131><E800 744><E041 3 2><E025 2>I wonder...<E049><E003 10>does it happen often?<E049><E003 8>\r\n<E164 3 87 1 2 6 0 0 1><E149 3 4 7><E139 3><E025 2>Being transferred internationally, <E049><E003 4>I mean?", "Ah oui, en y repensant, il avait mentionné quelque chose à ce sujet,\r\nn'est-ce pas ?\r\nJe me demande... est-ce chose fréquente ?\r\nÊtre muté à l'étranger, je veux dire ?\r\n...C'est la toute première fois que je vois pareille chose.");
                s = s.Replace("<E800 745><E145 18 4><E800 746><E041 18 7><E239><E025 3>...It's the first time I've ever encountered it.", "Ah oui, en y repensant, il avait mentionné quelque chose à ce sujet,\r\nn'est-ce pas ?\r\nJe me demande... est-ce chose fréquente ?\r\nÊtre muté à l'étranger, je veux dire ?\r\n...C'est la toute première fois que je vois pareille chose.");
                // UNMATCHED: s = s.Replace("<E800 748><E145 3 67><E800 749><E149 3 0 0><E800 751><E041 3 2><E333><E025 3>Oh!", "...");
                s = s.Replace("<E800 752><E145 18 0><E800 753><E041 18 7><E025 2>The Paris police welcoming an English detective is...<E003 10>\r\n<E025 3>almost inconceivable.", "Voir la police parisienne accueillir un inspecteur anglais à bras ouverts est...\r\npour ainsi dire impensable.\r\nJ'ignore par quel tour de passe-passe Gregson a bien pu négocier un tel accord.\r\n(...On dirait que ce mystère laisse même le Faucheur pantois.)");
                s = s.Replace("<E800 754><E563><E800 756><E145 18 9><E800 757><E003 15><E800 759><E041 18 7><E145 3 77><E239><E025 3>I can't imagine what kind of magic Gregson must have\r\nworked to put that arrangement in place.", "Voir la police parisienne accueillir un inspecteur anglais à bras ouverts est...\r\npour ainsi dire impensable.\r\nJ'ignore par quel tour de passe-passe Gregson a bien pu négocier un tel accord.\r\n(...On dirait que ce mystère laisse même le Faucheur pantois.)");
                s = s.Replace("<E800 760><E563><E800 761><E003 8><E800 763><E041 1 0><E025 3><E007>(...It sounds like that mystery has even the Reaper\r\nperplexed.)", "Voir la police parisienne accueillir un inspecteur anglais à bras ouverts est...\r\npour ainsi dire impensable.\r\nJ'ignore par quel tour de passe-passe Gregson a bien pu négocier un tel accord.\r\n(...On dirait que ce mystère laisse même le Faucheur pantois.)");
                s = s.Replace("<E800 764><E563><E800 765><E003 10><E800 767><E092 7><E800 768><E145 3 82><E800 769><E118 3 0.8><E800 770><E003 25><E800 772><E041 3 2><E025 3>I'm afraid to say...", "Je dois humblement avouer...\r\n...que nous ignorions tout du statut réel de l'inspecteur Gregson.\r\nOn raconte qu'il passait pour une véritable légende vivante à Scotland Yard.");
                s = s.Replace("<E800 773><E145 3 83><E800 774><E041 3 2><E025 2>...that we were very ignorant about <E145 18 0>Inspector Gregson's\r\nstanding.", "Je dois humblement avouer...\r\n...que nous ignorions tout du statut réel de l'inspecteur Gregson.\r\nOn raconte qu'il passait pour une véritable légende vivante à Scotland Yard.");
                s = s.Replace("<E800 775><E563><E800 777><E164 3 87 1 2 6 0 0 1><E800 778><E139 3><E800 780><E041 3 2><E025 2>We hear that <E049><E003 10><E025 3><E145 3 92>he was considered something of a legend at\r\nScotland Yard.<E085 2 9>", "Je dois humblement avouer...\r\n...que nous ignorions tout du statut réel de l'inspecteur Gregson.\r\nOn raconte qu'il passait pour une véritable légende vivante à Scotland Yard.");
                // UNMATCHED: s = s.Replace("<E800 781><E563><E800 783><E145 18 12><E800 784><E118 18 1.3><E800 785><E003 15><E800 787><E041 18 7><E025 7>...<E003 2>...<E003 4>...", "...");
                s = s.Replace("<E800 788><E041 18 7><E025 3>Again, <E049><E003 8><E025 2>it was ten years ago <E145 3 77><E118 3 0.7>that he first made a name for\r\nhimself.", "Là encore, c'est il y a dix ans qu'il s'est illustré pour la première fois.\r\nEn mettant au jour une preuve décisive qui révéla l'identité du Démon Assassin.\r\nSans l'approche singulière de Gregson sur cette affaire,\r\ncette découverte n'aurait jamais vu le jour.");
                s = s.Replace("<E800 789><E041 18 7><E025 2>By uncovering a decisive piece of evidence that exposed\r\nthe Professor's identity.", "Là encore, c'est il y a dix ans qu'il s'est illustré pour la première fois.\r\nEn mettant au jour une preuve décisive qui révéla l'identité du Démon Assassin.\r\nSans l'approche singulière de Gregson sur cette affaire,\r\ncette découverte n'aurait jamais vu le jour.");
                s = s.Replace("<E800 790><E563><E800 792><E145 18 3><E800 793><E118 18 0.5><E800 794><E003 10><E800 796><E041 18 7><E239><E025 2>If it wasn't for Gregson's <E006>singular approach<E005> to the case,<E049><E003 8>\r\nthe discovery would never have been made.", "Là encore, c'est il y a dix ans qu'il s'est illustré pour la première fois.\r\nEn mettant au jour une preuve décisive qui révéla l'identité du Démon Assassin.\r\nSans l'approche singulière de Gregson sur cette affaire,\r\ncette découverte n'aurait jamais vu le jour.");
                s = s.Replace("<E800 797><E041 1 0><E333><E025 2>What sort of approach?", "Quelle sorte d'approche ?\r\nAprès l'assassinat de mon frère, l'inspecteur a exigé une autopsie complète.\r\nBonté divine ! Il y a dix ans ?\r\n...En quoi cela est-il si surprenant ?");
                s = s.Replace("<E800 798><E041 18 7><E025 3>After my brother's life was taken, <E049><E003 8>the inspector pushed\r\nfor <E006>a full autopsy<E005>.", "Quelle sorte d'approche ?\r\nAprès l'assassinat de mon frère, l'inspecteur a exigé une autopsie complète.\r\nBonté divine ! Il y a dix ans ?\r\n...En quoi cela est-il si surprenant ?");
                s = s.Replace("<E800 799><E145 3 67><E800 800><E041 3 2><E333><E025 2>Oh my!<E049><E003 12> <E341><E338>Ten years ago?", "Quelle sorte d'approche ?\r\nAprès l'assassinat de mon frère, l'inspecteur a exigé une autopsie complète.\r\nBonté divine ! Il y a dix ans ?\r\n...En quoi cela est-il si surprenant ?");
                s = s.Replace("<E800 801><E041 1 0><E025 3>...Why is that so surprising?", "Quelle sorte d'approche ?\r\nAprès l'assassinat de mon frère, l'inspecteur a exigé une autopsie complète.\r\nBonté divine ! Il y a dix ans ?\r\n...En quoi cela est-il si surprenant ?");
                s = s.Replace("<E800 802><E563><E800 804><E145 18 12><E800 805><E118 18 0.6><E800 806><E003 15><E800 808><E041 18 7><E025 3>Autopsy <E145 3 64>was considered a desecration of the body at the\r\ntime, <E049><E003 6>and rarely performed.", "L'autopsie passait pour une profanation de sépulture à l'époque, et n'était que très rarement pratiquée.\r\nEt mon frère appartenait bien sûr à la haute noblesse. Cela rendait l'idée plus impensable encore.");
                s = s.Replace("<E800 809><E041 18 7><E025 3>And my brother was of course a noble.<E049><E003 10> That made the\r\nidea of it even more unthinkable.", "L'autopsie passait pour une profanation de sépulture à l'époque, et n'était que très rarement pratiquée.\r\nEt mon frère appartenait bien sûr à la haute noblesse. Cela rendait l'idée plus impensable encore.");
                s = s.Replace("<E800 811><E145 18 0><E800 812><E118 18 1.2><E800 814><E041 18 7><E025 2>But something Gregson had dug up in his investigations\r\nmade him determined it was necessary.", "Mais un indice déterré par Gregson lors de ses fouilles l'a convaincu de cette absolue nécessité.\r\nSa force de persuasion a fini par emporter l'adhésion de la Chambre des lords et grâce à cela...\r\nj'ai pu venger la mort de mon frère.");
                // UNMATCHED: s = s.Replace("<E800 815><E145 18 2><E800 816><E041 18 7><E025 3>His powerful conviction somehow influenced the House of\r\nLords and as a result...<E049><E003 10><E025 2>I could avenge my brother's death.", "...");
                s = s.Replace("<E800 817><E563><E800 818><E003 10><E800 820><E041 1 0><E025 3>So...<E003 12><E025 2><E333><E342>you must have had great <E006>confidence<E005> in the inspector's\r\nabilities, then.", "Ainsi... vous deviez vouer une immense confiance aux compétences\r\nde l'inspecteur.\r\nEt il est encore plus invraisemblable que vous ayez pu attenter à ses jours !\r\n...Je n'accorde ma confiance à personne.");
                s = s.Replace("<E800 821><E563><E800 823><E164 3 87 1 2 8 0 2 1><E800 824><E139 3><E800 826><E041 3 2><E025 1>And it's even more inconceivable that you would have\r\ntaken his life!", "Ainsi... vous deviez vouer une immense confiance aux compétences\r\nde l'inspecteur.\r\nEt il est encore plus invraisemblable que vous ayez pu attenter à ses jours !\r\n...Je n'accorde ma confiance à personne.");
                // UNMATCHED: s = s.Replace("<E800 827><E145 18 4><E800 828><E041 18 7><E025 7>...<E092 7><E003 2>...<E003 4>...<E145 3 64>", "...");
                s = s.Replace("<E800 829><E563><E800 831><E145 18 9><E800 832><E003 15><E800 834><E030 4 72 1 17><E800 836><E041 18 7><E239><E025 3>I don't have confidence in anyone.", "Ainsi... vous deviez vouer une immense confiance aux compétences\r\nde l'inspecteur.\r\nEt il est encore plus invraisemblable que vous ayez pu attenter à ses jours !\r\n...Je n'accorde ma confiance à personne.");
                // UNMATCHED: s = s.Replace("<E800 838><E145 3 67><E800 839><E117 3 8><E800 841><E041 3 2><E333><E025 2><E342>Oh...", "...");
                s = s.Replace("<E800 842><E563><E800 844><E145 18 0><E800 845><E118 18 1.3><E800 846><E003 10><E800 848><E041 18 7><E025 2>And I'm sure Gregson felt the same way.", "Et nul doute que Gregson éprouvait la même méfiance.\r\nIl ne voyait en moi que le sinistre Faucheur, à l'instar\r\nde tout Londres.");
                s = s.Replace("<E800 850><E145 18 2><E800 851><E118 18 1.2><E800 853><E041 18 7><E025 3>I've no doubt he thought of me only as the ominous\r\nReaper, <E049><E003 8>just like the rest of London.", "Et nul doute que Gregson éprouvait la même méfiance.\r\nIl ne voyait en moi que le sinistre Faucheur, à l'instar\r\nde tout Londres.");
                s = s.Replace("<E800 854><E563><E800 855><E003 15><E800 857><E145 18 0><E800 858><E003 4><E800 859><E549 8 1 40 3><E800 860><E168 3 0 5 10 40 3><E800 861><E131><E800 863><E085 2 11><E800 865><E041 1 0><E025 3><E007>(What really went on between Lord van Zieks and\r\nGregson, <E003 4>I wonder?)", "(Que s'est-il réellement passé entre Lord Van Peers et Gregson ?)\r\n(Quelle était la véritable nature de leurs relations ?)");
                s = s.Replace("<E800 866><E041 1 0><E330><E025 2><E007>(What was <E006>the true nature of their relationship<E007>?)", "(Que s'est-il réellement passé entre Lord Van Peers et Gregson ?)\r\n(Quelle était la véritable nature de leurs relations ?)");
                return s;
            };

            // [67] BB\script\output\_sce03_chr060_00_eng#18
            d[@"BB\script\output\_sce03_chr060_00_eng#18"] = (s) => {
                s = s.Replace("<RDFG 54428><E800 880><E145 18 0><E800 882><E041 1 0><E025 2>About the gun used to shoot the inspector that was found\r\nat the scene...", "À propos de l'arme du crime retrouvée sur les lieux qui a servi à abattre l'inspecteur...\r\nAh oui... Ce n'est point la mienne.");
                s = s.Replace("<E800 884><E145 18 12><E800 885><E118 18 1.1><E800 887><E041 18 7><E025 3>Ah yes...<E049><E003 15> <E025 2>That's not mine.", "À propos de l'arme du crime retrouvée sur les lieux qui a servi à abattre l'inspecteur...\r\nAh oui... Ce n'est point la mienne.");
                s = s.Replace("<E800 888><E563><E800 889><E003 7><E800 891><E041 1 0><E333><E342><E025 2>Really?<E003 12> Because common opinion seems to be that it is.", "Vraiment ? Pourtant tout le monde s'accorde à dire le contraire.\r\nQu'attendez-vous que je réponde à cela ?");
                // UNMATCHED: s = s.Replace("<E800 892><E041 18 7><E025 7>...<E003 2>...<E003 4>...<E003 12><E145 18 3><E118 18 0.6>\r\n<E239><E025 3>What do you expect me to say to that?", "...");
                s = s.Replace("<E800 893><E563><E800 896><E549 8 0 40 3><E800 897><E166 3 69 5 0 5 25 40 3><E800 898><E149 3 0 7><E800 899><E171 3 5 1 9 0><E800 900><E131><E800 902><E041 3 2><E025 2>Lord Stronghart informs us <E049><E003 8><E330>that you claim to have\r\n<E006>misplaced<E005> your firearm.", "Lord Harry Caine nous a informés que vous prétendiez avoir\r\négaré votre arme de service.\r\nAussi déshonorant que cela soit, je crains que ce ne soit la vérité.\r\nQuand l'avez-vous perdue alors ?");
                // UNMATCHED: s = s.Replace("<E800 903><E041 18 7><E025 7>...<E003 2>...<E145 18 12><E118 18 0.5><E003 4>...<E003 15>\r\n<E025 3>As embarrassing as that is, <E049><E003 8><E333>I'm afraid it's true.", "...");
                s = s.Replace("<E800 904><E041 1 0><E025 2><E145 3 64>When did you lose it, then?", "Lord Harry Caine nous a informés que vous prétendiez avoir\r\négaré votre arme de service.\r\nAussi déshonorant que cela soit, je crains que ce ne soit la vérité.\r\nQuand l'avez-vous perdue alors ?");
                s = s.Replace("<E800 905><E563><E800 907><E145 18 4><E800 908><E003 10><E800 910><E041 18 7><E025 3>That...<E003 12><E330>I don't know.", "Cela... je l'ignore.\r\nOh !\r\nOn m'a remis un revolver lors de mon entrée en fonction il y a dix ans.\r\nJ'ai dû le ranger quelque part, j'imagine.\r\nOu l'oublier dans un tiroir, sans doute.");
                s = s.Replace("<E800 912><E145 3 67><E800 913><E149 3 0 0><E800 915><E041 3 2><E025 2><E333><E341>Oh!", "Cela... je l'ignore.\r\nOh !\r\nOn m'a remis un revolver lors de mon entrée en fonction il y a dix ans.\r\nJ'ai dû le ranger quelque part, j'imagine.\r\nOu l'oublier dans un tiroir, sans doute.");
                s = s.Replace("<E800 916><E145 18 9><E800 917><E041 18 7><E025 2>I was issued with a revolver when I first became a\r\nprosecutor ten years ago.", "Cela... je l'ignore.\r\nOh !\r\nOn m'a remis un revolver lors de mon entrée en fonction il y a dix ans.\r\nJ'ai dû le ranger quelque part, j'imagine.\r\nOu l'oublier dans un tiroir, sans doute.");
                s = s.Replace("<E800 918><E041 18 7><E025 3>I must have stowed it somewhere, <E003 4>I suppose.<E049><E003 4>\r\n<E025 2><E145 18 0><E118 18 1.5><E003 20><E043>Or left it somewhere, <E003 4>perhaps.", "Cela... je l'ignore.\r\nOh !\r\nOn m'a remis un revolver lors de mon entrée en fonction il y a dix ans.\r\nJ'ai dû le ranger quelque part, j'imagine.\r\nOu l'oublier dans un tiroir, sans doute.");
                // UNMATCHED: s = s.Replace("<E800 919><E041 3 2><E025 7>...<E145 3 64><E149 3 0 7><E003 2>...<E003 4>...", "...");
                s = s.Replace("<E800 920><E172 3 -10 -5 18 3 2><E800 921><E041 3 2><E025 3>You have something in common with Lord van Zieks after\r\nall, <E049><E003 6>Mr Naruhodo:<E049><E003 6> <E164 3 84 1 2 23 0 0 1><E139 3>a talent for misplacing things.", "Vous avez un point commun avec Lord Van Peers après\r\ntout, monsieur Naruhodo : le don d'égarer vos affaires.");
                s = s.Replace("<E800 923><E145 3 67><E800 924><E149 3 0 0><E800 925><E172 3 -7 -3 3 2 10><E800 927><E041 1 0><E025 1><E045>No no no!<E003 12> This is nothing to do with me!<E003 12>\r\n<E342>Don't drag me into it!", "Non non non ! Cela n'a rien à voir avec moi !\r\nNe me mêlez point à cela !\r\nNe commettez point l'outrecuidance de m'associer à ce...\r\nJaponais !");
                s = s.Replace("<E800 928><E616><E800 930><E164 18 13 1 2 9 0 3 1><E800 931><E139 18><E800 933><E160 3><E800 934><E171 3 5 1 1 1><E800 936><E615><E800 937><E041 18 7><E025 1>Don't make the mistake of associating me with this...<E049><E003 12>\r\n<E342>Nipponese!", "Non non non ! Cela n'a rien à voir avec moi !\r\nNe me mêlez point à cela !\r\nNe commettez point l'outrecuidance de m'associer à ce...\r\nJaponais !");
                s = s.Replace("<E800 938><E563><E800 940><E145 3 72><E800 941><E003 15><E800 943><E041 3 2><E239><E025 3>Oh dear...<E003 12> <E341>The rift is very wide, <E049><E003 6>isn't it?", "Mince alors... Le fossé reste immense, n'est-ce pas ?\r\n(Ce n'est certes pas une preuve irréfutable.\r\nMais cela sent mauvais, c'est une certitude.)");
                s = s.Replace("<E800 944><E041 1 0><E025 3><E007>(So it's not decisive evidence, <E003 4>clearly.<E145 18 0><E003 12>\r\nBut it doesn't look good, <E003 6>that's for sure.)", "Mince alors... Le fossé reste immense, n'est-ce pas ?\r\n(Ce n'est certes pas une preuve irréfutable.\r\nMais cela sent mauvais, c'est une certitude.)");
                return s;
            };

            // [68] BB\script\output\_sce03_chr060_01_eng#1
            d[@"BB\script\output\_sce03_chr060_01_eng#1"] = (s) => {
                s = s.Replace("<RDFG 54553><E800 35><E145 18 0><E800 37><E041 1 0><E025 2>You once told me <E003 6>that you gladly allowed people to\r\nbelieve you were the Reaper...", "Vous m'avez dit jadis que vous laissiez volontiers les gens croire\r\nque vous étiez le Faucheur...\r\n...car cela contribuait à endiguer le grand banditisme à Londres.");
                s = s.Replace("<E800 38><E041 1 0><E025 2>...because it helped reduce the amount of serious crime\r\nthat took place in London.", "Vous m'avez dit jadis que vous laissiez volontiers les gens croire\r\nque vous étiez le Faucheur...\r\n...car cela contribuait à endiguer le grand banditisme à Londres.");
                s = s.Replace("<E800 39><E563><E800 41><E145 18 4><E800 42><E144 18><E800 44><E041 18 7><E025 2>If keeping quiet and playing the part benefits the cause –<E049><E003 10>\r\n<E025 3>a cause I myself am committed to pursuing...", "Si garder le silence et endosser ce rôle sert la cause –\r\nune cause pour laquelle j'ai dédié mon existence...\r\n...pourquoi choisirais-je de démentir quoi que ce soit ?");
