                s = s.Replace("<E800 91><E041 18 7><E025 3>Which can only mean...", "Non, le Faucheur dispose systématiquement de renseignements\r\nd'une précision chirurgicale sur les accusés.\r\nCe qui ne peut signifier qu'une chose...\r\n...qu'un membre influent de Scotland Yard tire les ficelles.");
