                s = s.Replace("<E800 115><E563><E800 117><E145 18 11><E800 118><E118 18 0.7><E800 119><E144 18><E800 120><E003 15><E800 122><E041 18 7><E025 3><E239><E092 4>...Tobias Gregson.", "Quelqu'un au... Vous ne voulez tout de même pas dire...?!\r\nIl m'a fallu de longues années, mais j'ai fini par identifier la\r\npièce maîtresse de cette confrérie du Faucheur :\r\n...Tobias Gregson.");
