                s = s.Replace("<E800 130><E563><E800 133><E141 127 5><E800 134><E144 127><E800 135><E148 110 64 0 5><E800 136><E144 110><E800 138><E041 110 5><E025 2>Well...<E049><E003 5><E164 110 70 1 2 8 0 1 1><E118 110 1.2><E139 110><E025 1>we're not going home empty-handed!", "Eh bien... nous ne repartirons pas bredouilles !");
