                s = s.Replace("<E800 177><E041 1 0><E025 3>Maria...<E003 12>Gorey?", "Maria... Gorey ?");
                s = s.Replace("<E800 178><E563><E800 180><E145 127 71><E800 181><E139 127><E800 183><E041 127 99><E025 2>Aye, <E049><E003 8>Sithe's daughter.<E049><E003 10> She did'nae have no more.<E049><E003 10>\r\nJust the one.", "Ouais, la fille de Pétrie. Elle n'en a point eu d'autre.\r\nJuste celle-là.\r\nMais la p'tiote a marché sur les traces de sa daronne.\r\nOn la voit jamais sans un scalpel entre les doigts.");
