                s = s.Replace("<E800 67><E041 1 0><E025 3><E007>(And...<E003 10><E330>did she just call the doctor, ‘Mama’?)", "(Et... vient-elle d'appeler le médecin « Maman » ?)");
                s = s.Replace("<E800 68><E563><MCRE 2 107 3><E800 207><E186 3 33><E003 3><E630 2 10><E003 3><E086 2 4><E070 2 1 1><E071><E120 33><E188><E065 0 0><E631 0><E632><E029 0 35><E800 209><E147 127 64><E800 211><E184><E029 0 35><E070 0 4 0><E071><E003 15><E800 215><E041 1 0><E025 3><E007>(Dr Sithe's daughter, <E003 8>Maria Gorey...<E003 14>\r\n<E025 3>We could do with talking to her...)", "(La fille de la Dre Pétrie, Maria Gorey...\r\nIl serait bon d'aller lui toucher deux mots...)");
