                s = s.Replace("<E800 237><E563><E800 240><E141 127 5><E800 241><E144 127><E800 242><E148 3 68 0 5><E800 243><E144 3><E800 245><E041 3 2><E025 3>Perhaps <E049><E003 8><E025 3>she was driven by a deep respect for her\r\nmother...", "Peut-être était-elle animée par un profond respect pour sa mère...");
