                s = s.Replace("<E800 258><E060 0 125 0 0><E800 259><E041 1 0><E025 2><E007>(Right.<E003 12> <E330>And the coroner responsible for this <E006>incomplete\r\nreport<E007>...)", "(C'est cela. Et le médecin légiste responsable de ce rapport incomplet...)");
