                s = s.Replace("<E800 287><E145 127 66><E800 288><E118 127 0.7><E800 290><E041 127 99><E025 3>After all, <E049><E003 8><E025 2><E330>that was <E006>a life-changing case<E005> for all of us.", "Après tout, c'te maudite affaire a chamboulé notre existence à tous.");
