                s = s.Replace("<E800 295><E041 1 0><E025 3>Well...<E003 10><E025 2>thank you very much.", "(Il nous faut impérativement interroger Mademoiselle Pétrie à ce sujet,\r\nje crois.)\r\nEh bien... merci infiniment.");
                s = s.Replace("<E800 296><E563><E800 297><E003 6><E800 299><E092 6><E800 300><E145 127 77><E800 301><E118 127 0.7><E800 302><E144 127><E800 304><E041 127 99><E239><E025 3>I'm no happy aboot any part o' this.", "J'suis point enchanté par tout ce tintouin.\r\nIl a fallu des années pour que les Londoniens oublient enfin toute l'histoire du Démon Assassin.");
                s = s.Replace("<E800 305><E041 127 99><E025 2>It took years for Londoners to finally forget the whole\r\nProfessor business.", "J'suis point enchanté par tout ce tintouin.\r\nIl a fallu des années pour que les Londoniens oublient enfin toute l'histoire du Démon Assassin.");
